window.EXAM_QUESTIONS=[{"id":"Q001","topic":1,"group":"Systems & indexing","stem":"The correct result is absent from a reranker's 100 candidates. What should improve first?","options":["Increase candidate-stage recall","Tune only the heavy ranker's learning rate","Calibrate CTR","Improve snippet typography"],"correct":0,"explanation":"The downstream model sees only candidates supplied to it. Improve sourcing, candidate K or lexical-semantic fusion.","origin":"Original practice"},{"id":"Q002","topic":2,"group":"Systems & indexing","stem":"A query has never appeared in click logs. Which feature is most dependable?","options":["Its historical query-document CTR","The query-document content match","Last week's click count for this exact query","A personalized click rate for an unknown user"],"correct":1,"explanation":"Content and semantic matching work without historical observations; memorized clicks cannot.","origin":"Original practice"},{"id":"Q003","topic":3,"group":"Systems & indexing","stem":"A model improves nDCG but doubles page latency. What is the sound conclusion?","options":["Deploy immediately","Reject every offline metric","Run a guarded online evaluation","Assume latency is not part of relevance"],"correct":2,"explanation":"The net user benefit is unknown until latency and other guardrails are measured.","origin":"Original practice"},{"id":"Q004","topic":4,"group":"Systems & indexing","stem":"Two systems contain exactly the same relevant documents in top 100, but one puts the first hit at rank 1 rather than 10. Which metric necessarily improves?","options":["Recall@100","MRR","Number of relevant documents","Corpus coverage"],"correct":1,"explanation":"The reciprocal of the first hit's rank increases; candidate recall is unchanged.","origin":"Original practice"},{"id":"Q005","topic":5,"group":"Systems & indexing","stem":"Median latency is steady but p99 doubles when CPU reaches 80%. Best response?","options":["Wait until CPU is 100%","Add capacity or reduce utilization","Increase logging verbosity only","Ignore p99"],"correct":1,"explanation":"Rare bursts queue behind already busy workers and amplify the slowest experiences.","origin":"Original practice"},{"id":"Q006","topic":6,"group":"Systems & indexing","stem":"A fixed worker pool overflows after response time triples while arrivals stay constant. Why?","options":["Throughput must triple","In-flight requests triple","CPU utilization must reach 100%","The user population triples"],"correct":1,"explanation":"Little's law gives N=X·R at the same boundary; fixed X and 3R imply 3N.","origin":"Original practice"},{"id":"Q007","topic":7,"group":"Systems & indexing","stem":"An API has idle preprocessing and saturated model inference. Which addition helps throughput?","options":["More preprocessing replicas","More inference capacity","More access logs","A new URL trie"],"correct":1,"explanation":"The bottleneck is the inference service demand; non-bottleneck capacity has little effect.","origin":"Original practice"},{"id":"Q008","topic":8,"group":"Systems & indexing","stem":"300 shards individually respond faster, but full dashboard p99 worsens. Why?","options":["Indexes are necessarily larger","It waits for the slowest of more responses","The arithmetic mean must worsen","The network has no partitions"],"correct":1,"explanation":"One straggler delays the whole fan-out; more dependencies increase the chance of encountering one.","origin":"Original practice"},{"id":"Q009","topic":9,"group":"Systems & indexing","stem":"Background compaction slows live queries. Best first action?","options":["Make compaction higher priority","Isolate or throttle compaction","Increase query timeout indefinitely","Drop ranking quality labels"],"correct":1,"explanation":"Compaction competes for CPU, I/O and cache; isolating it protects live latency.","origin":"Original practice"},{"id":"Q010","topic":10,"group":"Systems & indexing","stem":"A hotel site loses a cross-region link. Which action is safest?","options":["Continue all payments on stale state","Show cached listings but block unsafe bookings","Hide the entire website","Charge twice and reconcile later"],"correct":1,"explanation":"Read-only discovery tolerates staleness; booking must protect inventory/payment invariants.","origin":"Original practice"},{"id":"Q011","topic":11,"group":"Systems & indexing","stem":"Users primarily write from one city and friends read worldwide. Where place the primary?","options":["Far from writers to equalize reads","Near the main writers","In the least active region regardless of geography","Randomly for every request"],"correct":1,"explanation":"Writes need coordination with the primary; moving it near writers reduces latency without partitions.","origin":"Original practice"},{"id":"Q012","topic":12,"group":"Systems & indexing","stem":"A user updates their avatar and immediately sees the old one; other users may lag. What guarantee is missing?","options":["Global serializability for everything","Read-your-writes in the writer session","A Bloom filter","A query cache only"],"correct":1,"explanation":"The writer's session must be served at or beyond its latest acknowledged write.","origin":"Original practice"},{"id":"Q013","topic":13,"group":"Systems & indexing","stem":"A particular key gets most reads despite equal shard sizes. Which diagnosis fits?","options":["Perfect load balance","A hot key causing skew","Strong consistency everywhere","Too few vocabulary terms"],"correct":1,"explanation":"Traffic concentration rather than partition size is the limiting resource.","origin":"Original practice"},{"id":"Q014","topic":14,"group":"Systems & indexing","stem":"Small in-place price-field updates show 1.2 MB/s B+-tree versus 3 MB/s LSM device writes. Which is defensible?","options":["B+-tree for this workload, based on reads too","LSM always wins","Neither can support updates","Only replication matters"],"correct":0,"explanation":"The actual unit of rewritten data and compaction determine device writes; frequent point reads also matter.","origin":"Original practice"},{"id":"Q015","topic":15,"group":"Systems & indexing","stem":"A database advertises lower read, update and memory costs than LSM for every workload. What is the main caveat?","options":["It violates the workload-sensitive RUM trade-off","It must use SQL","It must contain a Bloom filter","Latency is irrelevant"],"correct":0,"explanation":"The conjecture highlights fundamental competing overheads; improvements may be workload-specific.","origin":"Original practice"},{"id":"Q016","topic":16,"group":"Systems & indexing","stem":"An exact Windows error code is split by tokenization and no longer matches. What should change?","options":["More stemming","An exact-code-safe analyzer at index and query time","Click-model debiasing","Longer cache TTL"],"correct":1,"explanation":"The analyzer is an index/query contract; code search prioritizes exact tokens.","origin":"Original practice"},{"id":"Q017","topic":17,"group":"Systems & indexing","stem":"Which law helps estimate new distinct terms as the collection grows?","options":["Zipf","Heaps","Little's law","CAP"],"correct":1,"explanation":"Heaps describes vocabulary size versus total tokens; Zipf describes term-frequency skew.","origin":"Original practice"},{"id":"Q018","topic":18,"group":"Systems & indexing","stem":"Two documents differ by one navigation line and have unrelated SHA-256 values. Next step?","options":["Declare them unrelated","Compare shingle similarity via candidates","Use a longer SHA hash","Reduce the corpus by deleting both"],"correct":1,"explanation":"Near-duplicate detection needs a similarity representation and candidate-generation method.","origin":"Original practice"},{"id":"Q019","topic":19,"group":"Systems & indexing","stem":"Two shingle sets share 4 items out of a 7-item union. What is Jaccard?","options":["4/7","4/11","7/4","1−4/7"],"correct":0,"explanation":"The denominator is the union of both sets.","origin":"Original practice"},{"id":"Q020","topic":20,"group":"Systems & indexing","stem":"For J=0.8 and 100 independent MinHashes, how many coordinates agree on average?","options":["About 8","About 20","About 80","Exactly 100"],"correct":2,"explanation":"Each coordinate matches with probability 0.8, so expectation is 80.","origin":"Original practice"},{"id":"Q021","topic":21,"group":"Systems & indexing","stem":"Missing moderately similar pairs is much worse than extra verification. With fixed k, what change helps recall?","options":["More rows per band","More bands with fewer rows each","Require two matching bands","Remove exact verification"],"correct":1,"explanation":"More bands offer more chances of a matching band, shifting the S-curve left.","origin":"Original practice"},{"id":"Q022","topic":22,"group":"Systems & indexing","stem":"A search service needs merged distinct-user counts from many shards. Which sketch?","options":["SpaceSaving","HyperLogLog","MinHash","t-digest"],"correct":1,"explanation":"HLL registers merge naturally for approximate cardinality.","origin":"Original practice"},{"id":"Q023","topic":23,"group":"Systems & indexing","stem":"A service must answer exact adjacent-word phrases. What must postings store?","options":["Only total corpus tokens","Term positions per document","Only static PageRank","Only raw URLs"],"correct":1,"explanation":"Adjacency can be checked when positions are indexed.","origin":"Original practice"},{"id":"Q024","topic":24,"group":"Systems & indexing","stem":"Why is a failed per-document signature map safe to retry?","options":["It uses global mutable counters","It is deterministic and side-effect-free","It reads a different document","It requires no hash seeds"],"correct":1,"explanation":"The framework can discard partial output and recompute exactly the same logical result.","origin":"Original practice"},{"id":"Q025","topic":25,"group":"Systems & indexing","stem":"One term appears in 10 documents, another in 1 million. How should an AND query start?","options":["Start with the million-doc list","Start with the 10-doc list","Scan the full corpus","Ignore the rare term"],"correct":1,"explanation":"The rare term cheaply restricts candidates first.","origin":"Original practice"},{"id":"Q026","topic":26,"group":"Systems & indexing","stem":"A disk-bound search needs higher query throughput. Why might compression help?","options":["It always reduces CPU","It reduces I/O bytes enough to outweigh decode cost","It eliminates ranker training","It removes the need for postings"],"correct":1,"explanation":"Bandwidth can dominate and reading fewer bytes saves more time than decoding costs.","origin":"Original practice"},{"id":"Q027","topic":27,"group":"Systems & indexing","stem":"New documents must appear in seconds and query p99 remains strict. Which trade-off matters?","options":["Smaller flushes vs segment/merge cost","Removing term dictionaries","Always using a single giant segment","Dropping all background compaction"],"correct":0,"explanation":"Freshness is a compaction dial, not a free operation.","origin":"Original practice"},{"id":"Q028","topic":28,"group":"Ranking & signals","stem":"A search returns 50,000 documents matching a query but gives no order. What's missing?","options":["A stopword list only","A relevance scoring policy","An exact content hash","A partition-tolerant write"],"correct":1,"explanation":"Boolean matching decides membership; rankers produce an ordering among candidates.","origin":"Original practice"},{"id":"Q029","topic":29,"group":"Ranking & signals","stem":"Which similarity removes vector-magnitude effects?","options":["Raw inner product","Cosine","Hamming count always","Jaccard on ordered strings"],"correct":1,"explanation":"Cosine divides by both vector norms.","origin":"Original practice"},{"id":"Q030","topic":30,"group":"Ranking & signals","stem":"Two terms occur equally often in a document; one appears in almost every corpus document. Which gets higher IDF?","options":["The common term","The rarer term","They are equal","Whichever is alphabetically first"],"correct":1,"explanation":"Rarer document-frequency terms yield larger inverse-document-frequency weights.","origin":"Original practice"},{"id":"Q031","topic":31,"group":"Ranking & signals","stem":"What is BM25's main response to keyword stuffing?","options":["Linear tf reward","TF saturation","Removing all rare terms","Only PageRank"],"correct":1,"explanation":"Saturation gives diminishing marginal score as term frequency grows.","origin":"Original practice"},{"id":"Q032","topic":32,"group":"Ranking & signals","stem":"Under equal cost of relevance mistakes, which item should appear first?","options":["P(rel)=0.2","P(rel)=0.8","The longer document","The newest URL regardless of score"],"correct":1,"explanation":"PRP favors the result with higher relevance probability under the stated assumptions.","origin":"Original practice"},{"id":"Q033","topic":33,"group":"Ranking & signals","stem":"What does setting b=0 do in BM25?","options":["Maximum length penalty","Remove document-length normalization","Remove TF saturation","Remove term rarity"],"correct":1,"explanation":"The length multiplier becomes 1, independent of document length.","origin":"Original practice"},{"id":"Q034","topic":34,"group":"Ranking & signals","stem":"A marketplace values title matches more than body matches. Best lexical adaptation?","options":["Field-weighted BM25F","Remove the index","Use only user location","Use raw title length only"],"correct":0,"explanation":"BM25F captures differing evidential value of fields while retaining TF saturation.","origin":"Original practice"},{"id":"Q035","topic":35,"group":"Ranking & signals","stem":"Why does a query-likelihood model smooth term probabilities?","options":["To avoid zero probability on unseen terms","To guarantee all docs score equally","To eliminate corpus statistics","To create Boolean filters"],"correct":0,"explanation":"Corpus smoothing prevents one missing term from multiplying the likelihood by zero.","origin":"Original practice"},{"id":"Q036","topic":36,"group":"Ranking & signals","stem":"A lexical scorer cannot distinguish two text-identical pages with different authority. What is missing?","options":["A non-text authority signal","More stemming","A shorter dictionary","Different shingle lengths"],"correct":0,"explanation":"PageRank or document-quality features can supply evidence external to the terms.","origin":"Original practice"},{"id":"Q037","topic":37,"group":"Ranking & signals","stem":"Why can PageRank be inexpensive at query time?","options":["It is computed offline and stored per document","It recomputes the full web graph for every query","It needs no links","It only applies to exact phrases"],"correct":0,"explanation":"The graph computation happens outside the serving path.","origin":"Original practice"},{"id":"Q038","topic":38,"group":"Ranking & signals","stem":"Which description fits HITS rather than PageRank?","options":["One global offline score","Separate hub and authority scores on a query subgraph","A TF-only score","A Bloom membership test"],"correct":1,"explanation":"HITS models two recursive roles and is commonly query-dependent.","origin":"Original practice"},{"id":"Q039","topic":39,"group":"Ranking & signals","stem":"A model combines BM25, freshness, PageRank and CTR. What is the modeling setup?","options":["Learning to rank from pair features","Only Boolean retrieval","Pure Jaccard sketching","Exact SHA deduplication"],"correct":0,"explanation":"Feature-based learning maps each query-document pair to a score.","origin":"Original practice"},{"id":"Q040","topic":40,"group":"Ranking & signals","stem":"Which training idea weights pairs by the nDCG change caused by swapping them?","options":["Raw MSE regression","LambdaRank-style gradient weighting","Exact Jaccard","Unweighted logistic CTR"],"correct":1,"explanation":"Metric-aware weighting emphasizes mistakes that alter top rankings.","origin":"Original practice"},{"id":"Q041","topic":41,"group":"Ranking & signals","stem":"Which combination describes LambdaMART?","options":["Lambda gradients + gradient-boosted regression trees","MinHash + locality-sensitive banding","Bloom + HLL","PageRank + cosine only"],"correct":0,"explanation":"It is metric-aware gradient boosting over tree ensembles.","origin":"Original practice"},{"id":"Q042","topic":42,"group":"Ranking & signals","stem":"A new reranker doubles quality on judged pairs but breaks p99. What's the proper response?","options":["Use fewer candidates or a staged cascade and remeasure","Discard monitoring","Assume quality guarantees utility","Recompute the graph on every query"],"correct":0,"explanation":"Stage design trades improved scoring against serving budget and upstream recall.","origin":"Original practice"},{"id":"Q043","topic":43,"group":"Ranking & signals","stem":"Which is a document-only feature suitable for offline precomputation?","options":["Current query length","PageRank","User device hour","Query-document phrase proximity"],"correct":1,"explanation":"PageRank depends on link graph, not the incoming query.","origin":"Original practice"},{"id":"Q044","topic":44,"group":"Ranking & signals","stem":"A result gets high CTR but very short dwell and high immediate return. What might the metric miss?","options":["Satisfaction and quality","The number of hash functions","Document frequency only","Replica quorum size"],"correct":0,"explanation":"CTR measures clicks, not necessarily fulfilled information need.","origin":"Original practice"},{"id":"Q045","topic":45,"group":"Ranking & signals","stem":"The same result loses CTR when randomly moved lower. Which explanation fits?","options":["Reduced exposure/examination","Changed document relevance","Changed link graph always","A new parser"],"correct":0,"explanation":"Attention falls with position even when item content is fixed.","origin":"Original practice"},{"id":"Q046","topic":46,"group":"Ranking & signals","stem":"A user clicks rank 2 and stops. How interpret no click on rank 8?","options":["Strong negative label","Likely unexamined, not clear evidence","Positive label","Proof of a broken index"],"correct":1,"explanation":"The cascade says later positions might never be examined.","origin":"Original practice"},{"id":"Q047","topic":47,"group":"Ranking & signals","stem":"Why can inverse propensity weights be unstable?","options":["They are always zero","Rarely examined positions get huge weights","They require no logs","They are identical for all positions"],"correct":1,"explanation":"Dividing by tiny examination probabilities magnifies random outcomes.","origin":"Original practice"},{"id":"Q048","topic":48,"group":"Ranking & signals","stem":"Two CTR models rank identically, but one doubles every predicted probability. What can change?","options":["AUC necessarily doubles","Expected auction value and calibration","The document index length","The term dictionary"],"correct":1,"explanation":"AUC depends largely on order; value calculations depend on probability magnitude.","origin":"Original practice"},{"id":"Q049","topic":49,"group":"Ranking & signals","stem":"What does feature hashing mainly solve?","options":["Fixed memory for huge identifiers","Automatic calibration","Perfect separation of all collisions","Removal of labels"],"correct":0,"explanation":"Hashing limits table growth while accepting occasional collisions.","origin":"Original practice"},{"id":"Q050","topic":50,"group":"Ranking & signals","stem":"A feature table built over the test day's clicks greatly increases offline accuracy. What is the first suspicion?","options":["Leakage from future/current labels","Better retrieval recall alone","A stronger SHA hash","An LSH threshold issue"],"correct":0,"explanation":"The model may be reading the answer through its features.","origin":"Original practice"},{"id":"Q051","topic":51,"group":"Ranking & signals","stem":"Which approach generalizes to an unseen feature pair from embeddings of each feature?","options":["Plain one-hot LR cross coefficient","Factorization machine","Exact Boolean intersection","SHA-256"],"correct":1,"explanation":"FM weights an interaction through learned vectors, not a distinct memorized pair weight.","origin":"Original practice"},{"id":"Q052","topic":52,"group":"Ranking & signals","stem":"Which branch usually memorizes frequent exact crosses in Wide & Deep?","options":["Wide linear branch","Only the embedding MLP","A Bloom filter","LSM compaction"],"correct":0,"explanation":"The wide side captures explicit head-pattern exceptions, while deep side can interpolate.","origin":"Original practice"},{"id":"Q053","topic":53,"group":"Ranking & signals","stem":"When predictions cluster around 0.3 but observed clicks are near 0.1, what is wrong?","options":["Only query recall","Calibration/overconfidence","MinHash independence","CAP choice"],"correct":1,"explanation":"Predicted probabilities are systematically too high compared with frequencies.","origin":"Original practice"},{"id":"Q054","topic":54,"group":"Ranking & signals","stem":"AUC improves on validation but online conversion declines. Which diagnosis is plausible?","options":["Serving/feature skew or wrong proxy target","Too many independent MinHashes","A missing shingle union","A better PACELC write leader"],"correct":0,"explanation":"Offline proxy improvements do not establish causality or online value.","origin":"Original practice"},{"id":"Q055","topic":55,"group":"Ranking & signals","stem":"A novel query has no past impressions. What is the safest source of evidence?","options":["Its historical CTR","Content matching","Historical click-through of the exact pair","Its non-click log after rank 100"],"correct":1,"explanation":"Content works even where behavioral features have no observations.","origin":"Original practice"},{"id":"Q056","topic":56,"group":"A/B testing","stem":"An experimental feature is only used by motivated volunteers and shows higher CTR. Can this prove causal benefit?","options":["Yes, because CTR is measured","No, selection confounds the effect","Yes, if the sample is large","Only after using BM25"],"correct":1,"explanation":"Volunteers may differ in intent; random assignment is absent.","origin":"Original practice"},{"id":"Q057","topic":57,"group":"A/B testing","stem":"Users see alternating UI variants on successive requests and learn from both. Which change helps?","options":["Stable user-level assignment","More frequent reshuffling","Ignoring carryover","A larger trie"],"correct":0,"explanation":"Keeping treatment stable per user avoids within-user contamination and confusing experiences.","origin":"Original practice"},{"id":"Q058","topic":58,"group":"A/B testing","stem":"A treatment improves CTR but violates a pre-set severe latency guardrail. Safest decision?","options":["Launch on CTR alone","Do not launch without resolving guardrail harm","Ignore the guardrail because p<0.05","Delete slow users from analysis"],"correct":1,"explanation":"Good metrics do not excuse unacceptable operational damage.","origin":"Original practice"},{"id":"Q059","topic":59,"group":"A/B testing","stem":"A test reports p=0.03. Which interpretation is correct?","options":["H0 has probability 0.03","Data this extreme or more would have probability 0.03 under H0","Treatment succeeds with probability 0.97","There is a 3% business loss risk"],"correct":1,"explanation":"A p-value conditions on H0; it is not a posterior probability of hypotheses.","origin":"Original practice"},{"id":"Q060","topic":60,"group":"A/B testing","stem":"A treatment shows p=0.18 with a wide CI that includes a large gain. Best conclusion?","options":["Proved no effect","Inconclusive; effect may still matter","Treatment is harmful with 82% probability","Guaranteed zero lift"],"correct":1,"explanation":"Non-significance means insufficient evidence against H0 in that test, not proof that H0 is correct.","origin":"Original practice"},{"id":"Q061","topic":61,"group":"A/B testing","stem":"A latency-heavy model gives a trivial CTR gain with p<0.001. What matters for launch?","options":["The p-value alone","Practical effect size and guardrails","Only the null hypothesis name","Only the number of variants"],"correct":1,"explanation":"Significance describes evidence under a model; cost-benefit determines product value.","origin":"Original practice"},{"id":"Q062","topic":62,"group":"A/B testing","stem":"A 95% CI for lift is [−1%,+5%]. What is supported?","options":["Guaranteed positive effect","Range includes both harm and benefit","Exactly 95% chance of lift","Zero sample error"],"correct":1,"explanation":"The interval includes plausible negative and positive effects under its procedure.","origin":"Original practice"},{"id":"Q063","topic":63,"group":"A/B testing","stem":"A real +2% lift is missed by an underpowered study. Which mistake?","options":["Type I","Type II","No error because p>0.05","A Bloom false positive"],"correct":1,"explanation":"Failing to detect a real prespecified effect is a false negative (Type II).","origin":"Original practice"},{"id":"Q064","topic":64,"group":"A/B testing","stem":"Twenty unchanged variants are each tested at 5%. What happens to at-least-one false-positive risk?","options":["It stays exactly 5%","It increases substantially","It becomes zero","It equals the average effect size"],"correct":1,"explanation":"More independent chances to cross a threshold increase family-wise false discoveries.","origin":"Original practice"},{"id":"Q065","topic":65,"group":"A/B testing","stem":"A team stops immediately at the first unadjusted p<0.05 after daily peeking. What's the concern?","options":["Optional stopping inflates false positives","The treatment becomes more randomized","nDCG cannot be computed","The data is automatically calibrated"],"correct":0,"explanation":"Repeated opportunities to stop on chance noise alter the test's error properties.","origin":"Original practice"},{"id":"Q066","topic":66,"group":"A/B testing","stem":"An A/B test configured 50/50 has 65/35 assigned users. First step?","options":["Declare the treatment winner","Investigate allocation/logging (SRM)","Change the p-value threshold only","Run MinHash"],"correct":1,"explanation":"Sample ratio mismatch points to experiment validity rather than outcome quality.","origin":"Original practice"},{"id":"Q067","topic":67,"group":"A/B testing","stem":"What baseline is appropriate for CUPED?","options":["A metric measured before exposure","A click caused by the treatment","A conversion after treatment","A rating requested only in treatment"],"correct":0,"explanation":"A pretreatment correlated covariate can reduce variance without blocking the treatment pathway.","origin":"Original practice"},{"id":"Q068","topic":68,"group":"A/B testing","stem":"An A/A test repeatedly shows large group differences. What should be checked?","options":["Randomization and event logging","BM25 k1 first","Only document stemming","The index's Bloom filter"],"correct":0,"explanation":"When treatment is identical, persistent differences suggest platform imbalance or measurement flaws.","origin":"Original practice"},{"id":"Q069","topic":69,"group":"A/B testing","stem":"Two tests estimate nearly identical positive lifts; one has p=0.049 and the other p=0.051. Best conclusion?","options":["They necessarily contradict","Their evidence may be nearly identical","One proves H0 true","The second proves no practical effect"],"correct":1,"explanation":"A hard significance threshold should not replace continuous assessment of evidence and uncertainty.","origin":"Original practice"},{"id":"X001","topic":5,"group":"Systems & indexing","stem":"A service improves average response time slightly, yet 0.1% of requests take seconds after a traffic spike. What should be graphed next?","options":["Only average CPU over a week","Queue depth and p99 against utilization","The URL dictionary size","Average term length"],"correct":1,"explanation":"The symptom is tail queuing near saturation; p99 and queue depth reveal it.","origin":"Original practice"},{"id":"X002","topic":6,"group":"Systems & indexing","stem":"A system processes 80 requests/s with mean residence time 0.5 seconds. How many requests are in flight on average?","options":["16","40","80","160"],"correct":1,"explanation":"Little's law yields N=XR=80×0.5=40.","origin":"Original practice"},{"id":"X003","topic":6,"group":"Systems & indexing","stem":"A closed system keeps 100 shoppers active; they each think 9 seconds and the server responds in 1 second. What throughput follows in steady state?","options":["1/s","10/s","100/s","1000/s"],"correct":1,"explanation":"X=N/(R+Z)=100/10=10 queries/s.","origin":"Original practice"},{"id":"X004","topic":7,"group":"Systems & indexing","stem":"A dependency gets called four times for every completed request at 10 ms/visit. Another is called once at 20 ms. Which has greater service demand?","options":["The first dependency","The second dependency","Equal","Insufficient information about disk price"],"correct":0,"explanation":"D=V×S: first 40 ms/request, second 20 ms/request.","origin":"Original practice"},{"id":"X005","topic":8,"group":"Systems & indexing","stem":"An aggregation fans out to 200 services, each rarely slow. Which change directly reduces the chance any slow service delays the aggregate?","options":["Fan out to 500","Reduce required dependencies or hedge safely","Increase request body size","Switch to an LSM table"],"correct":1,"explanation":"More independent dependencies increase the probability of encountering a straggler.","origin":"Original practice"},{"id":"X006","topic":9,"group":"Systems & indexing","stem":"An overnight index merge consumes the CPU set also serving interactive search. Which performance metric is most likely to reveal harm?","options":["Only total document count","Serving p99 latency","MinHash collision probability","Average word length"],"correct":1,"explanation":"Batch contention chiefly harms tail latency of live serving.","origin":"Original practice"},{"id":"X007","topic":10,"group":"Systems & indexing","stem":"A two-region balance transfer cannot reach its authoritative record during a partition. Which branch is safest?","options":["A: authorize conflicting balances","C: reject or delay conflicting transfer","A: trust stale balance and reconcile money errors later","Always drop read requests too"],"correct":1,"explanation":"Irreversible financial invariants call for consistency on the partition branch.","origin":"Original practice"},{"id":"X008","topic":10,"group":"Systems & indexing","stem":"A search index shows a deleted item during a temporary partition but the purchase is verified later. What has been sacrificed?","options":["Index freshness","Checkout consistency necessarily","Password integrity","Little's law"],"correct":0,"explanation":"An advisory listing may be stale while the binding transaction remains safe.","origin":"Original practice"},{"id":"X009","topic":11,"group":"Systems & indexing","stem":"A global product stores user-owned preferences, and writes almost all originate from one region. What is a normal-operation latency concern?","options":["Leader placed far from the writer","Too many hash buckets only","A very short posting list","Keyword stuffing"],"correct":0,"explanation":"Leader/master distance adds coordination latency even without a partition.","origin":"Original practice"},{"id":"X010","topic":12,"group":"Systems & indexing","stem":"A system promises users they immediately see their own profile edits but reads from lagging followers. What minimal change preserves that promise?","options":["Require every visitor to read the primary forever","Pin post-write reads to sufficiently fresh replicas","Delete old images from all backups immediately","Use lower BM25 b"],"correct":1,"explanation":"Session freshness can be guaranteed without forcing globally synchronous consistency.","origin":"Original practice"},{"id":"X011","topic":13,"group":"Systems & indexing","stem":"An architecture copies every shard into three regions but has no partitioning across servers. What does the replication alone fail to guarantee?","options":["More copies","Data capacity through independent shards","Fault tolerance","Some read serving capacity"],"correct":1,"explanation":"Replicas reproduce the same data; sharding distributes distinct records.","origin":"Original practice"},{"id":"X012","topic":14,"group":"Systems & indexing","stem":"A mostly append-only stream writes millions of immutable events but seldom needs random reads. Which storage choice is plausible?","options":["LSM-style append and batch compaction","Every event as a B+-tree root update","A trie for every event payload","A full PageRank iteration"],"correct":0,"explanation":"Sequential append and batching are strengths of LSM-like designs.","origin":"Original practice"},{"id":"X013","topic":15,"group":"Systems & indexing","stem":"A proposal accelerates point reads using two extra indexes. What should a reviewer immediately ask?","options":["How much writes and storage increase?","Whether the author used Python","Why all queries are Boolean","What is the team's logo?"],"correct":0,"explanation":"Auxiliary access paths have update and space overhead.","origin":"Original practice"},{"id":"X014","topic":16,"group":"Systems & indexing","stem":"For 'US visas' a generic case-folder maps 'US' to 'us' and hurts relevance. What lesson follows?","options":["Never tokenize text","Normalization can damage meaning","Always stem more","Skip query analysis"],"correct":1,"explanation":"Analyzer policies are bets about the query domain and must be evaluated.","origin":"Original practice"},{"id":"X015","topic":17,"group":"Systems & indexing","stem":"A query combines a rare diagnosis code and common word 'the'. Which term should guide candidate intersection?","options":["Common 'the'","Rare diagnosis code","Randomly alternate","Neither term can be indexed"],"correct":1,"explanation":"Shortest postings usually filter candidates fastest.","origin":"Original practice"},{"id":"X016","topic":18,"group":"Systems & indexing","stem":"SHA-256 finds no duplicates in scraped pages where only footer ads differ. Which claim is true?","options":["Hashes prove all are distinct in content","Exact hashes miss near-duplicates","A longer hash solves near-matching","Bloom filters calculate Jaccard"],"correct":1,"explanation":"SHA detects byte-level equality, not semantic/structural resemblance.","origin":"Original practice"},{"id":"X017","topic":20,"group":"Systems & indexing","stem":"Two documents have Jaccard 0.5, but their MinHash signatures agree in 8/10 positions. Is MinHash broken?","options":["Yes, exact equality must be 5","No, a finite random estimate has variance","Yes, hashing must be cryptographic","No, Jaccard itself is undefined"],"correct":1,"explanation":"Signature collisions estimate Jaccard with sampling error.","origin":"Original practice"},{"id":"X018","topic":21,"group":"Systems & indexing","stem":"Increasing rows per band from 4 to 10 while reducing band count at fixed k does what?","options":["Makes candidate rule stricter","Makes it universally more permissive","Removes false negatives","Eliminates exact verification"],"correct":0,"explanation":"A full band collision becomes harder as r increases, moving threshold right.","origin":"Original practice"},{"id":"X019","topic":21,"group":"Systems & indexing","stem":"Two dissimilar pages collide in one band and enter candidates. What should happen next?","options":["Delete both pages immediately","Compare their actual shingle similarity before dedup","Train a CTR model","Assume they are identical"],"correct":1,"explanation":"Banding produces candidates, not final similarity decisions.","origin":"Original practice"},{"id":"X020","topic":22,"group":"Systems & indexing","stem":"A sketch says a URL is absent. The application cannot tolerate mistakenly missing an already seen URL. Which guarantee matters?","options":["Bloom has no false negatives","Bloom has no false positives","HLL is exact","SpaceSaving always supports membership"],"correct":0,"explanation":"Bloom 'not present' is reliable under standard insertion-only assumptions.","origin":"Original practice"},{"id":"X021","topic":22,"group":"Systems & indexing","stem":"A stream needs an unbiased frequency estimator for a rarely seen query. Which is apt?","options":["Count-Min because it only overcounts","Count-Sketch with random signs","HyperLogLog","t-digest"],"correct":1,"explanation":"Signed collisions cancel in expectation for Count-Sketch.","origin":"Original practice"},{"id":"X022","topic":22,"group":"Systems & indexing","stem":"A service wants to estimate the 99.9th percentile of request latency over merged shards. Which sketch?","options":["MinHash","KLL/t-digest","Bloom","SimHash"],"correct":1,"explanation":"Mergeable quantile sketches estimate distribution tails.","origin":"Original practice"},{"id":"X023","topic":23,"group":"Systems & indexing","stem":"A search wants 'San Francisco' as an exact phrase. A postings index contains docIDs and tf but no positions. What is needed?","options":["Positional postings or a separate phrase index","A larger HLL","Different CAP policy","Only more PageRank"],"correct":0,"explanation":"Doc occurrence alone cannot prove adjacency.","origin":"Original practice"},{"id":"X024","topic":24,"group":"Systems & indexing","stem":"To build an inverted index across 1000 machines, where is the major network stage?","options":["Local parsing only","Shuffle by term","Local checksum only","The HTML rendering"],"correct":1,"explanation":"Map outputs must be grouped across machines by term before reduce.","origin":"Original practice"},{"id":"X025","topic":25,"group":"Systems & indexing","stem":"For a query 'cat AND quantum' with df(cat)=1M and df(quantum)=10, which list should be examined first?","options":["cat","quantum","Neither, scan all docs","Only the dictionary root"],"correct":1,"explanation":"The short posting list cheaply restricts candidates.","origin":"Original practice"},{"id":"X026","topic":26,"group":"Systems & indexing","stem":"A compressed postings list reads four times fewer bytes but costs extra CPU decoding. When is it still faster?","options":["When I/O savings exceed decoding cost","Never","Only if the query has no terms","Only if PageRank is nonzero"],"correct":0,"explanation":"Compression helps when storage bandwidth is limiting.","origin":"Original practice"},{"id":"X027","topic":33,"group":"Ranking & signals","stem":"A spam page adds 100 identical keywords but also gets much longer. Which BM25 mechanisms resist the boost?","options":["Unbounded tf","TF saturation and length normalization","Boolean OR alone","Hashing the URL"],"correct":1,"explanation":"Saturation and b length normalization reduce reward from repetition and bloat.","origin":"Original practice"},{"id":"X028","topic":37,"group":"Ranking & signals","stem":"A lexical score ranks two term-identical pages equally despite one being linked by authoritative websites. What additional signal fits?","options":["PageRank","More term saturation","Another stopword list","More LSH bands"],"correct":0,"explanation":"Authority is external to document terms and can be computed from links.","origin":"Original practice"},{"id":"X029","topic":40,"group":"Ranking & signals","stem":"A ranker models document relevance labels independently, yet correct order within each query is weak. Which learning objective is more aligned?","options":["Pairwise/listwise ranking loss","Only tokenization","Bloom lookup","Shingle Jaccard"],"correct":0,"explanation":"Relative losses directly optimize ordering preferences or metrics.","origin":"Original practice"},{"id":"X030","topic":41,"group":"Ranking & signals","stem":"A few hand-coded threshold interactions dominate ranker quality. Which model is naturally suited?","options":["Gradient-boosted trees","Simple Boolean AND only","Cryptographic hashing","HLL"],"correct":0,"explanation":"Trees represent nonlinear feature thresholds effectively.","origin":"Original practice"},{"id":"X031","topic":44,"group":"Ranking & signals","stem":"A training log records thousands of unclicked results that users never scrolled to. What is wrong with using all as negative examples?","options":["Exposure is unobserved; non-click is not necessarily dislike","They are necessarily positive","The index must be empty","A p-value cannot be computed"],"correct":0,"explanation":"Unexamined items do not generate negative preference evidence.","origin":"Original practice"},{"id":"X032","topic":45,"group":"Ranking & signals","stem":"A result shown at position 2 is moved to position 8 while content stays constant and CTR falls. What does a click model need?","options":["Position/examination propensity","A different corpus hash","More stemming","A larger B+-tree"],"correct":0,"explanation":"Observed clicks conflate exposure with attractiveness.","origin":"Original practice"},{"id":"X033","topic":47,"group":"Ranking & signals","stem":"A bottom-ranked item's estimated examination propensity is 0.01. Which risk does inverse propensity weighting face?","options":["A 100x weight and high variance","Guaranteed zero weight","No possible correction","It changes relevance labels to 1"],"correct":0,"explanation":"Low propensities amplify individual outcomes.","origin":"Original practice"},{"id":"X034","topic":49,"group":"Ranking & signals","stem":"A CTR system with billions of rarely seen categorical ids needs fixed memory and fast online updates. Which baseline is natural?","options":["Hashed sparse LR with FTRL","Full graph HITS per impression","Exact all-pairs Jaccard","Brute force pair sorting"],"correct":0,"explanation":"Hashing bounds memory; FTRL updates sparse models at scale.","origin":"Original practice"},{"id":"X035","topic":50,"group":"Ranking & signals","stem":"A recommender includes an item's cumulative clicks through the evaluation period as a feature. Why might offline AUC be inflated?","options":["Future label leakage","Insufficient LSH bands","Wrong Jaccard denominator","Strong read consistency"],"correct":0,"explanation":"Training receives label-derived information that would not exist at inference time.","origin":"Original practice"},{"id":"X036","topic":51,"group":"Ranking & signals","stem":"A user-category pair never occurred in training but each side appeared with many other pairs. Which method can extrapolate an interaction?","options":["Factorization machine","One-hot exact cross only","SHA-256","Postings intersection"],"correct":0,"explanation":"Latent factor vectors share strength across interactions.","origin":"Original practice"},{"id":"X037","topic":53,"group":"Ranking & signals","stem":"Model A predicts clicks at 0.1 and observed rate near 0.1. Model B predicts 0.3 for those same cases. What property differs?","options":["Calibration","Boolean recall only","Shingle size","SSD bandwidth"],"correct":0,"explanation":"Model A's probability matches empirical frequency while B overstates it.","origin":"Original practice"},{"id":"X038","topic":55,"group":"Ranking & signals","stem":"A ranker trained only on pairwise click counts sees a query with no history. What backstop helps?","options":["BM25 or semantic content evidence","Set all results to zero forever","Randomly promote ads without content","Use a longer cache TTL"],"correct":0,"explanation":"Content-based features generalize to unseen queries.","origin":"Original practice"},{"id":"X039","topic":56,"group":"A/B testing","stem":"A feature is rolled out to all California users while New York users remain controls. What's the causal concern?","options":["Regional confounding","Incorrect MinHash collision rate","TF saturation","Too few FST prefixes"],"correct":0,"explanation":"Geography may correlate with outcomes; allocation is not randomized within the same eligible population.","origin":"Original practice"},{"id":"X040","topic":58,"group":"A/B testing","stem":"An experiment increases clicks but also doubles crash rate. What should the analysis emphasize?","options":["Pre-set operational guardrails","Only p-value for clicks","Only the number of impressions","The query vocabulary size"],"correct":0,"explanation":"Product benefit must be evaluated subject to harm constraints.","origin":"Original practice"},{"id":"X041","topic":59,"group":"A/B testing","stem":"A product manager says p=0.01 means '99% chance the new ranker is better'. What is the correction?","options":["p is calculated under a null model, not a posterior probability","p means 1% CTR","p is a confidence interval","p proves no downside"],"correct":0,"explanation":"The significance-test p-value is not P(treatment better|data).","origin":"Original practice"},{"id":"X042","topic":60,"group":"A/B testing","stem":"A test has p=0.4 and a wide interval spanning −15% to +20%. What can the team conclude?","options":["No change exists","The study is inconclusive, including meaningful harm/benefit","Exactly 60% chance of benefit","The feature is proven safe"],"correct":1,"explanation":"Large uncertainty prevents claiming equivalence or no harm.","origin":"Original practice"},{"id":"X043","topic":61,"group":"A/B testing","stem":"A change boosts a metric by 0.0001% with p<10⁻⁶ on huge traffic but adds 50 ms latency. What should decide launch?","options":["Effect size and guardrail costs","Only p-value","Only test sample size","Only number of clicks"],"correct":0,"explanation":"Statistical detectability does not imply useful product impact.","origin":"Original practice"},{"id":"X044","topic":62,"group":"A/B testing","stem":"An experiment's confidence interval for revenue lift is [−2%,+8%]. Which statement is justified?","options":["Positive impact is guaranteed","Results are compatible with losses and gains","Posterior probability of gain is exactly 95%","The sample must be invalid"],"correct":1,"explanation":"The interval includes negative and positive effects under the procedure.","origin":"Original practice"},{"id":"X045","topic":63,"group":"A/B testing","stem":"A team fears missing a real but small improvement. What statistical quantity should planning address?","options":["Power for the minimum detectable effect","Bloom false positive only","PageRank damping","Stemming strength"],"correct":0,"explanation":"Power relates to detection probability for a specified real effect.","origin":"Original practice"},{"id":"X046","topic":64,"group":"A/B testing","stem":"A search team tests 50 ranking features independently and promotes the largest significant gain. What needs attention?","options":["Multiple testing and selection","Only exact phrases","PACL simulation","Number of shards"],"correct":0,"explanation":"Selecting the best among many tests inflates false discovery risks.","origin":"Original practice"},{"id":"X047","topic":65,"group":"A/B testing","stem":"A sequential dashboard has ordinary p-values crossing 0.05 randomly at different hours. Best policy?","options":["Use a preplanned stopping rule or valid sequential test","Stop at first crossing regardless of plan","Ignore time stamps","Compute a Jaccard set"],"correct":0,"explanation":"Optional stopping alters error rates unless designed into the test.","origin":"Original practice"},{"id":"X048","topic":66,"group":"A/B testing","stem":"An A/B experiment's assigned-group counts are 70/30 despite 50/50 configuration. What should happen before significance claims?","options":["Investigate assignment and event collection","Declare the larger group winner","Decrease sample size","Rebuild lexical index"],"correct":0,"explanation":"Severe sample-ratio mismatch can indicate broken randomization or logging.","origin":"Original practice"},{"id":"X049","topic":68,"group":"A/B testing","stem":"An A/A test with identical code in both arms has persistently large differences. What is the highest-priority diagnosis?","options":["Instrumentation or randomization issue","Unseen semantic documents","Missing MinHash signatures","Overlong postings"],"correct":0,"explanation":"The equal-treatment design should expose pipeline bias rather than a true treatment effect.","origin":"Original practice"}];
